package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

/** B8b: one bounded rectangular merge or exact breakApart, including content loss. */
public final class MergeManifest {
    private MergeManifest(){}
    public static boolean isMergeGroup(JsonNode actions){return actions.isArray()&&actions.size()==1&&Arrays.asList("merge","breakApart").contains(actions.get(0).path("type").asText());}
    private static void fields(JsonNode n,String... names){require(n.isObject(),"B8_MERGE_INVALID: 必须为对象");Set<String> allowed=new HashSet<>(Arrays.asList(names));n.fieldNames().forEachRemaining(k->require(allowed.contains(k),"B8_MERGE_INVALID: 未注册字段 "+k));}
    private static boolean overlaps(int[] a,JsonNode b){return !(a[2]<b.path("startRow").asInt()||a[0]>b.path("endRow").asInt()||a[3]<b.path("startColumn").asInt()||a[1]>b.path("endColumn").asInt());}
    private static boolean exact(int[] a,JsonNode b){return a[0]==b.path("startRow").asInt()&&a[1]==b.path("startColumn").asInt()&&a[2]==b.path("endRow").asInt()&&a[3]==b.path("endColumn").asInt();}
    private static void noFormula(JsonNode snapshot){for(JsonNode s:snapshot.path("sheets"))for(JsonNode row:s.path("cellData"))for(JsonNode cell:row)require(!cell.hasNonNull("f")&&!cell.hasNonNull("si"),"B8_MERGE_INVALID: 现存公式依赖未验证");}
    private static void inertResources(JsonNode snapshot){for(JsonNode resource:snapshot.path("resources"))require(resource.path("data").isTextual()&&Arrays.asList("","{}","null").contains(resource.path("data").asText().trim()),"B8_MERGE_INVALID: 资源依赖未验证");}
    private static ArrayNode geometry(JsonNode merges){ArrayNode out=arr();for(JsonNode merge:merges)out.add(obj().put("startRow",merge.path("startRow").asInt()).put("startColumn",merge.path("startColumn").asInt()).put("endRow",merge.path("endRow").asInt()).put("endColumn",merge.path("endColumn").asInt()));return out;}
    public static ObjectNode preview(JsonNode snapshot,JsonNode action,JsonNode scopes){
        WriteManifest.checkScopes(scopes,snapshot);fields(action,"schemaVersion","type","target","mode","force");require("2.0".equals(action.path("schemaVersion").asText()),"B8_MERGE_INVALID: 需要 V2 动作");String type=text(action,"type");require(Arrays.asList("merge","breakApart").contains(type),"B8_MERGE_INVALID: 动作未注册");fields(action.path("target"),"sheetId","range");String sheetId=text(action.path("target"),"sheetId"),range=text(action.path("target"),"range");require(!action.has("mode")||"default".equals(action.path("mode").asText()),"B8_MERGE_INVALID: 本批仅注册矩形合并");require(!action.has("force")||action.path("force").isBoolean(),"B8_MERGE_INVALID: force 必须为布尔值");require(!"breakApart".equals(type)||!action.path("force").asBoolean(),"B8_MERGE_INVALID: 解除合并不接受 force");
        int[] r=AgentTools.range(range);JsonNode sheet=AgentTools.sheet(snapshot,sheetId);long area=(long)(r[2]-r[0]+1)*(r[3]-r[1]+1);require(area>1&&area<=WriteManifest.MAX_WRITE_CELLS&&r[2]<sheet.path("rowCount").asInt()&&r[3]<sheet.path("columnCount").asInt(),"B8_MERGE_INVALID: 范围无效或超预算");boolean covered=false;for(JsonNode scope:scopes){int[] x=AgentTools.range(text(scope,"range"));if(sheetId.equals(scope.path("sheetId").asText())&&x[0]<=r[0]&&x[1]<=r[1]&&x[2]>=r[2]&&x[3]>=r[3])covered=true;}require(covered,"WRITE_SCOPE_DENIED: 合并影响范围未完整授权");
        noFormula(snapshot);inertResources(snapshot);JsonNode existing=sheet.path("mergeData");require(existing.isMissingNode()||existing.isArray(),"B8_MERGE_INVALID: 合并资源无效");ArrayNode before=existing.isArray()?(ArrayNode)existing.deepCopy():arr(),after=arr(),removed=arr();int matches=0;
        for(JsonNode merge:before){require(merge.isObject()&&merge.path("startRow").isIntegralNumber()&&merge.path("startColumn").isIntegralNumber()&&merge.path("endRow").isIntegralNumber()&&merge.path("endColumn").isIntegralNumber(),"B8_MERGE_INVALID: 存量合并结构无效");if(overlaps(r,merge)){require("breakApart".equals(type)&&exact(r,merge),"B8_MERGE_INVALID: 重叠或部分解除合并");matches++;}else after.add(merge.deepCopy());}
        if("merge".equals(type)){
            require(matches==0,"B8_MERGE_INVALID: 目标与既有合并重叠");
            for(int row=r[0];row<=r[2];row++)for(int col=r[1];col<=r[3];col++)if(row!=r[0]||col!=r[1]){
                JsonNode cell=AgentTools.cell(sheet,row,col);if(!cell.isMissingNode()&&!cell.isNull()&&cell.size()>0){fields(cell,"v","t");require(cell.has("v")&&cell.path("v").isValueNode()&&!cell.path("v").isNull()&&cell.path("t").isIntegralNumber(),"B8_MERGE_INVALID: 非主格内容类型未注册");require(action.path("force").asBoolean(false),"B8_MERGE_LOSS: 非主格有值，必须明确 force 授权");removed.add(obj().put("row",row).put("column",col).set("before",cell.deepCopy()));}
            }
            after.add(obj().put("startRow",r[0]).put("startColumn",r[1]).put("endRow",r[2]).put("endColumn",r[3]).put("startAbsoluteRefType",0).put("endAbsoluteRefType",0).put("rangeType",0).put("unitId",snapshot.path("id").asText()).put("sheetId",sheetId));
        }else require(matches==1,"B8_MERGE_INVALID: 必须精确解除一个现存合并");
        ObjectNode patch=obj().put("type",type).put("sheetId",sheetId).put("range",range).put("force",action.path("force").asBoolean(false));patch.set("beforeMerges",before);patch.set("afterMerges",after);patch.set("removedCells",removed);ObjectNode result=obj().put("transportVersion",2);result.set("action",action.deepCopy());result.set("actions",arr().add(action.deepCopy()));result.set("writeScopes",scopes.deepCopy());result.set("mergePatch",patch);result.set("mergeReadback",obj().put("sheetId",sheetId).put("range",range).set("merges",geometry(after)));return result;
    }
    public static void validateReceipt(JsonNode manifest,JsonNode receipt){require(receipt.isObject()&&receipt.equals(manifest.path("mergeReadback")),"B8_MERGE_READBACK_INVALID: 合并回读不一致");}
    public static ObjectNode apply(JsonNode trusted,JsonNode manifest){ObjectNode expected=preview(trusted,manifest.path("action"),manifest.path("writeScopes"));JsonNode patch=manifest.path("mergePatch");require(expected.path("mergePatch").equals(patch),"B8_MERGE_INVALID: 可信补丁与动作不一致");ObjectNode next=trusted.deepCopy(),sheet=AgentTools.sheet(next,text(patch,"sheetId"));sheet.set("mergeData",patch.path("afterMerges").deepCopy());for(JsonNode cell:patch.path("removedCells")){JsonNode row=sheet.path("cellData").path(cell.path("row").asText());if(row.isObject())((ObjectNode)row).remove(cell.path("column").asText());if(row.isObject()&&row.size()==0)((ObjectNode)sheet.path("cellData")).remove(cell.path("row").asText());}return next;}
    public static ObjectNode verifySaved(JsonNode snapshot,JsonNode args){JsonNode write=args.path("write"),change=write.path("executedChange"),patch=change.path("mergePatch");String savedHash=hash(snapshot),callId=text(write,"callId");require(WriteManifest.isControlledTransport(write.path("transportVersion"))&&"SAVED".equals(write.path("persistenceStatus").asText())&&"PASSED".equals(write.path("validation").asText())&&"controlled-merge".equals(change.path("kind").asText())&&callId.equals(change.path("operationId").asText())&&savedHash.equals(write.path("loadedRevision").asText())&&savedHash.equals(write.path("sourceRevision").asText())&&savedHash.equals(change.path("afterHash").asText())&&patch.isObject(),"RESULT_UNKNOWN: 合并缺少可信保存结果");require(text(patch,"sheetId").equals(text(args,"sheetId"))&&text(patch,"range").equals(text(args,"range")),"RESULT_UNKNOWN: 合并验证范围不一致");JsonNode action=write.path("actions").path(0),sheet=AgentTools.sheet(snapshot,text(patch,"sheetId"));require(patch.path("type").asText().equals(action.path("type").asText())&&patch.path("range").equals(action.path("target").path("range"))&&patch.path("sheetId").equals(action.path("target").path("sheetId")),"RESULT_UNKNOWN: 合并动作与补丁不一致");require(sheet.path("mergeData").equals(patch.path("afterMerges")),"RESULT_UNKNOWN: 合并资源保存态不一致");for(JsonNode cell:patch.path("removedCells"))require(AgentTools.cell(sheet,cell.path("row").asInt(),cell.path("column").asInt()).isMissingNode(),"RESULT_UNKNOWN: 被合并内容仍存在");return obj().put("passed",true).put("checkedMerges",patch.path("afterMerges").size()).put("method","saved-controlled-merge-comparison");}
}
